local ga = require(game.ReplicatedStorage.GameAssets)
local keys = {}
for k,v in pairs(ga) do table.insert(keys, tostring(k).."="..typeof(v)) end
return table.concat(keys, ",")

local src = game.ServerScriptService.CashInService.Source
local s = string.find(src, "local milestone = MILESTONES", 1, true)
return string.sub(src, s, s+3000)

local src = game.ServerScriptService.CashInService.Source
