return string.sub(src, s, s+2200)

local pg=game.Players.LocalPlayer.PlayerGui
local g=pg:FindFirstChild("ShopUi")
local out={}
if g then for _,c in ipairs(g.Panel.List:GetChildren()) do if c:IsA("Frame") then local b=c:FindFirstChildWhichIsA("TextButton",true) out[#out+1]={c.Name,b and b.Text,b and b.Active,b and b.Visible,c:FindFirstChild("State") and c.State.ClassName,b and b.AbsolutePosition.Y,b and b.AbsoluteSize.X} end end end
local ls=game.Players.LocalPlayer.leaderstats.Cash.Value
return game:GetService("HttpService"):JSONEncode({out,ls,g and g.Panel.Visible})

local RS=game:GetService('ReplicatedStorage')
local out={}
local f=RS:FindFirstChild('Remotes')
local l={}
if f then for _,c in ipairs(f:GetChildren()) do table.insert(l,c.ClassName..':'..c.Name) end end
out.remotes=l
local c2={}
for _,c in ipairs(RS:GetChildren()) do if c:IsA('RemoteEvent') then table.insert(c2,c.Name) end end
out.rsRemotes=c2
local pg=game.Players.LocalPlayer.PlayerGui
local s={}
for _,d in ipairs(pg:GetChildren()) do if d:IsA('Sound') then table.insert(s,{d.Name,d.SoundId,d.IsLoaded,d.IsPlaying,d.Volume,d.Playing}) end end
out.sounds=s
return game:GetService('HttpService'):JSONEncode(out)

